// Odpowiedź + źródła (adnotacje url_citation). Tekst czyścimy z markdownu i linków — źródła pokazuje aplikacja.
const msg = $json.choices?.[0]?.message || {};
const answer = String(msg.content || '').replace(/\(\[[^\]]*\]\([^)]*\)(, *\[[^\]]*\]\([^)]*\))*\)/g, '')
