      {"op": "add", "name": "nazwa listy", "items": ["punkt", …], "reset": false}
      {"op": "edit", "list": indeks, "name": "nowa nazwa" albo null, "add": ["…"], "remove": ["dokładny tekst punktu"], "rename": [{"from": "…", "to": "…"}], "reset": true|false|null}
      {"op": "delete", "list": indeks},
   "fields": null = bez zmian, albo pełna nowa lista [{"label": maks. 20, "value": maks. 60}] (maks. 4),
   "look": null albo {"tint": "lavender"|"mint"|"blue"|"pink"|"sky", "icon": "clock"|"cycle"|"list"|"globe"|"note"|"building"|"tv"|"health"|"car"|"home"|"cart"|"work"|"money"|"sport"|"people"|"doc"|"food"|"travel"},
   "widget_remove": true|false,
